  function prepareTurn(id,offset=0,startedAt=0){stopTimers();if(state.analysisMode==='full_report'&&state.report?.turnId!==id){state.report=null;state.reportTurnId='';state.reportSequence++;state.reportLoading='';reportBox.replaceChildren(node('p','正在读取这份完整报告的扫描与整理进度…','mp-muted'));delete reportBox.dataset.signature;}state.turnId=id;state.batchOffset=offset;state.snapshot=null;state.submittedAt=startedAt;state.lastResponseAt=0;startButton.disabled=true;cancelButton.disabled=true;resumeButton.hidden=true;deepButton.disabled=true;deepReportBox.replaceChildren();delete deepReportBox.dataset.signature;analysisBox.replaceChildren();delete analysisBox.dataset.signature;analysisPager.replaceChildren();summaryBox.replaceChildren();delete summaryBox.dataset.signature;progress.textContent='正在读取已保存的分析进度…';renderLiveProgress({status:'queued',progress:{}});saveSelection();}
  function turnMatchesSelection(data){const p=data.progress||{},packageId=data.package_id||p.package_id;if(packageId&&packageId!==state.packageId)return false;const entityId=data.entity_id!==undefined?data.entity_id:p.entity_id;if(entityId!==undefined&&String(entityId||'')!==state.entityId)return false;const addresses=data.addresses||p.addresses||[data.address||p.address].filter(Boolean);return !Array.isArray(addresses)||!addresses.length||addresses.some(address=>String(address).toLowerCase()===state.address.toLowerCase());}
