    try{const data=await api('/api/mail/person-analyses/'+encodeURIComponent(id)+'/report');if(!alive(epoch)||sequence!==state.reportSequence)return;if(!turnMatchesSelection(data)||data.analysis_mode!=='full_report'||!reportReady(data))throw new Error('完整报告不属于当前人物或尚未完成，暂不能作为深度分析依据。');state.reportTurnId=id;state.report={...data.report,turnId:id,ready:true};renderReportFile(reportBox,data.report,id,true);updateDeepAvailability(Boolean(state.snapshot&&!terminal(state.snapshot.status)));saveSelection();}
    catch(error){if(alive(epoch)&&sequence===state.reportSequence){state.report=null;updateDeepAvailability(false);deepNotice.textContent='未能恢复完整报告：'+format(error.message||error)+'。';deepNotice.append(button('重新读取完整报告',()=>loadSourceReport(id),'mp-text-button'));}}
    finally{if(sequence===state.reportSequence)state.reportLoading='';}
